            <ul>
              <li><p :style="'color:'+numColor[index]">{{ item.allbuy }}</p><p class="title" :style="'color:'+lableColor[index]">{{ $t('vip.vip02') }}</p></li>
              <li><p :style="'color:'+numColor[index]">{{ item.weekbuy }}</p><p class="title" :style="'color:'+lableColor[index]">{{ $t('vip.vip03') }}</p></li>
              <li><p :style="'color:'+numColor[index]">{{ item.weekmoney }}</p><p class="title" :style="'color:'+lableColor[index]">{{ $t('vip.vip04') }}</p></li>
            </ul>
          </div> -->
        </div>
      </swiper-slide>
      <!-- <div slot="pagination" class="swiper-pagination" /> -->
    </swiper>
    <div v-if="viplist.length>0" class="vip-line">
      <div class="small">
        <div class="icon" />
        <div v-if="currentIndex>0">{{ 'VIP'+(currentIndex-1) }}</div>
      </div>
      <div class="medium">
