import vip12 from '@/assets/vip/tag/vip12.png'
export default {
  components: {
    TitleLine,
    Info
  },
  props: {
  },
  data() {
    return {
      title: this.$t('vip.vip01'),
      swiperOptions: {
        effect: 'coverflow',
        grabCursor: true,
        centeredSlides: true,
        slidesPerView: 'auto',
        coverflowEffect: {
          rotate: 50,
          stretch: 0,
          depth: 100,
          modifier: 1,
          slideShadows: true
        },
        // slidesPerView: 3,
        // // slidesPerView: 'auto',
        // spaceBetween: 30,
        pagination: {
          el: '.swiper-pagination',
          clickable: true
        }
      },
      viplist: [],
      fanlist: [],
      currentIndex: null,
      vipbgList: [VIP0, VIP1, VIP2, VIP3, VIP4, VIP5, VIP6, VIP7, VIP8, VIP9, VIP10, VIP11, VIP12],
      vipTagList: [vip0, vip1, vip2, vip3, vip4, vip5, vip6, vip7, vip8, vip9, vip10, vip11, vip12],
      lableColor: ['rgba(51,64,80,0.7)', 'rgba(23,49,37,0.7)', 'rgba(5,43,63,0.7)', 'rgba(25,33,91,0.7)', 'rgba(96,46,0,0.7)', 'rgba(92,35,1,0.7)', 'rgba(110,15,15,0.7)', 'rgba(114,8,70,0.7)', 'rgba(74,11,98,0.7)', 'rgba(73,9,160,1)', 'rgba(48,19,127,0.7)', 'rgba(222,213,255,0.7)', 'rgba(251,247,243,0.7)'],
      numColor: ['#334050', '#173125', '#052B3F', '#19215B', '#602E00', '#552001', '#631313', '#580535', '#4E1166', '#2F174E', '#2E1377', '#FFFFFF', '#FFFFFF'],
